// Assets for the report card PDF.
//
// SCHOOL_MARK_DATA_URI is the school's lion-and-book mark (transparent PNG), inlined as a data URI so
// the PDF route can draw it without the file being traced into the serverless bundle.
//
// The faint "school photo" behind the page content is optional: drop a photo at
// src/assets/school-photo.jpg (or .png) and it is picked up automatically (see readSchoolPhoto in
// reportCardPdf.tsx). Without a file, the report card simply shows the logo watermark.
export const SCHOOL_MARK_DATA_URI =
  "data:image/png;base64,";
